export TF_VAR_garage_app_secret_access_key="${GARAGE_APP_SECRET_ACCESS_KEY:?add GARAGE_APP_SECRET_ACCESS_KEY to trivia-more-infra → /staging}"
export TF_VAR_app_infisical_client_id="${STAGING_APP_INFISICAL_CLIENT_ID:?add STAGING_APP_INFISICAL_CLIENT_ID to trivia-more-infra → /staging}"
